// ONFI_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module ONFI_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic [23:0] c_cmd_row,
  input logic [2:0] c_cmd_op,
  input logic [15:0] c_cmd_col,
  input logic [11:0] c_cmd_len,
  input logic [7:0] c_wr_data,
  input logic [7:0] c_rd_data,
  input logic [7:0] c_status,
  input logic  c_cmd_valid,
  input logic  c_cmd_ready,
  input logic  c_wr_valid,
  input logic  c_wr_ready,
  input logic  c_rd_valid,
  input logic  c_rd_ready,
  input logic  c_done,
  input logic  c_ev_fail,
  input logic  c_ev_timeout
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 10;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:9];          // model of every stored word
  logic [7:0] m_set;                // interrupt bits set this clock
  logic m_state_CMD;          // full / valid pulse / available
  logic m_state_WR;          // full / valid pulse / available
  logic m_state_RD;          // full / valid pulse / available

  always_comb begin
    m_set = '0;
    if (c_done) m_set[0] = 1'b1;
    if (c_ev_fail) m_set[1] = 1'b1;
    if (c_ev_timeout) m_set[2] = 1'b1;
    if (m_state_CMD && c_cmd_ready) m_set[3] = 1'b1;
    if (m_wr && m_map && (m_idx == 5 || m_idx == 6) && m_state_CMD) m_set[4] = 1'b1;
    if (m_state_WR && c_wr_ready) m_set[5] = 1'b1;
    if (m_wr && m_map && (m_idx == 7) && m_state_WR) m_set[6] = 1'b1;
    if (c_rd_valid && !m_state_RD) m_set[7] = 1'b1;
    if (c_rd_valid && m_state_RD && (m_rd && m_map && m_idx == 8)) m_set[7] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h0;
      m_w[6] <= 32'h0;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_state_CMD <= 0;
      m_state_WR <= 0;
      m_state_RD <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'hFF;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5 && !m_state_CMD) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'h7FFFFFF;
      if (m_wr && m_map && m_idx == 6 && !m_state_CMD) m_w[6] <= ((m_w[6] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFF;
      if (m_wr && m_map && m_idx == 6 && !m_state_CMD) m_state_CMD <= 1;
      if (m_state_CMD && c_cmd_ready) m_state_CMD <= 0;
      if (m_wr && m_map && m_idx == 7 && !m_state_WR) m_w[7] <= ((m_w[7] & ~m_be) | (PWDATA & m_be)) & 32'hFF;
      if (m_wr && m_map && m_idx == 7 && !m_state_WR) m_state_WR <= 1;
      if (m_state_WR && c_wr_ready) m_state_WR <= 0;
      if (c_rd_valid && (!m_state_RD || (m_rd && m_map && m_idx == 8))) begin
        m_w[8] <= (32'(c_rd_data[7:0]) << 0);
        m_state_RD <= 1;
      end else if ((m_rd && m_map && m_idx == 8)) m_state_RD <= 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h4F4E0200;
      1: return m_w[1];
      2: return m_w[2];
      3: return 32'({m_state_RD, m_state_WR, m_state_CMD});
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      7: return m_w[7];
      8: return m_w[8];
      9: return (32'(c_status) << 0);
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][7:0] & m_w[2][7:0]))
  `SVA_INV(a_core_cmd_row, c_cmd_row == m_w[5][23:0])
  `SVA_INV(a_core_cmd_op, c_cmd_op == m_w[5][26:24])
  `SVA_INV(a_core_cmd_col, c_cmd_col == m_w[6][15:0])
  `SVA_INV(a_core_cmd_len, c_cmd_len == m_w[6][27:16])
  `SVA_INV(a_core_wr_data, c_wr_data == m_w[7][7:0])
  `SVA_INV(a_core_cmd_valid, c_cmd_valid == m_state_CMD)
  `SVA_INV(a_core_wr_valid, c_wr_valid == m_state_WR)
  `SVA_INV(a_core_rd_ready, c_rd_ready == (!m_state_RD || (m_rd && m_map && m_idx == 8)))
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_cmd_row == 24'h0 && c_cmd_op == 3'h0 && c_cmd_col == 16'h0 && c_cmd_len == 12'h0 && c_wr_data == 8'h0 && !c_cmd_valid && !c_wr_valid && c_rd_ready)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
  `FC(wr_IRQ_ENABLE, m_wr && m_map && m_idx == 2)
  `FC(rd_FLAGS, m_rd && m_map && m_idx == 3)
  `FC(wr_FLAGS, m_wr && m_map && m_idx == 3)
  `FC(rd_SCRATCH, m_rd && m_map && m_idx == 4)
  `FC(wr_SCRATCH, m_wr && m_map && m_idx == 4)
  `FC(rd_CMD0, m_rd && m_map && m_idx == 5)
  `FC(wr_CMD0, m_wr && m_map && m_idx == 5)
  `FC(rd_CMD1, m_rd && m_map && m_idx == 6)
  `FC(wr_CMD1, m_wr && m_map && m_idx == 6)
  `FC(rd_WR, m_rd && m_map && m_idx == 7)
  `FC(wr_WR, m_wr && m_map && m_idx == 7)
  `FC(rd_RD, m_rd && m_map && m_idx == 8)
  `FC(wr_RD, m_wr && m_map && m_idx == 8)
  `FC(rd_STATUS, m_rd && m_map && m_idx == 9)
  `FC(wr_STATUS, m_wr && m_map && m_idx == 9)
  `FC(unmapped_read, m_rd && !m_map && PADDR[1:0] == 0)
  `FC(unmapped_write, m_wr && !m_map && PADDR[1:0] == 0)
  `FC(misaligned_read, m_rd && PADDR[1:0] != 0)
  `FC(misaligned_write, m_wr && PADDR[1:0] != 0)
  `FC(partial_strobe_write, m_wr && m_map && PSTRB != 4'h0 && PSTRB != 4'hF)
  `FC(zero_strobe_write, m_wr && m_map && PSTRB == 4'h0)
  `FC(back_to_back, PSEL && PENABLE ##1 PSEL && !PENABLE)
  `FC(idle_between, PSEL && PENABLE ##1 !PSEL)
  `FC(irq_DONE_set, m_set[0])
  `FC(irq_DONE_cleared, m_w[1][0] && m_wr && m_map && m_idx == 1 && PWDATA[0] && PSTRB[0])
  `FC(irq_DONE_masked, m_w[1][0] && !m_w[2][0])
  `FC(irq_DONE_drives_pin, m_w[1][0] && m_w[2][0] && irq)
  `FC(irq_FAIL_set, m_set[1])
  `FC(irq_FAIL_cleared, m_w[1][1] && m_wr && m_map && m_idx == 1 && PWDATA[1] && PSTRB[0])
  `FC(irq_FAIL_masked, m_w[1][1] && !m_w[2][1])
  `FC(irq_FAIL_drives_pin, m_w[1][1] && m_w[2][1] && irq)
  `FC(irq_TIMEOUT_set, m_set[2])
  `FC(irq_TIMEOUT_cleared, m_w[1][2] && m_wr && m_map && m_idx == 1 && PWDATA[2] && PSTRB[0])
  `FC(irq_TIMEOUT_masked, m_w[1][2] && !m_w[2][2])
  `FC(irq_TIMEOUT_drives_pin, m_w[1][2] && m_w[2][2] && irq)
  `FC(irq_CMD_DONE_set, m_set[3])
  `FC(irq_CMD_DONE_cleared, m_w[1][3] && m_wr && m_map && m_idx == 1 && PWDATA[3] && PSTRB[0])
  `FC(irq_CMD_DONE_masked, m_w[1][3] && !m_w[2][3])
  `FC(irq_CMD_DONE_drives_pin, m_w[1][3] && m_w[2][3] && irq)
  `FC(irq_CMD_OVF_set, m_set[4])
  `FC(irq_CMD_OVF_cleared, m_w[1][4] && m_wr && m_map && m_idx == 1 && PWDATA[4] && PSTRB[0])
  `FC(irq_CMD_OVF_masked, m_w[1][4] && !m_w[2][4])
  `FC(irq_CMD_OVF_drives_pin, m_w[1][4] && m_w[2][4] && irq)
  `FC(irq_WR_DONE_set, m_set[5])
  `FC(irq_WR_DONE_cleared, m_w[1][5] && m_wr && m_map && m_idx == 1 && PWDATA[5] && PSTRB[0])
  `FC(irq_WR_DONE_masked, m_w[1][5] && !m_w[2][5])
  `FC(irq_WR_DONE_drives_pin, m_w[1][5] && m_w[2][5] && irq)
  `FC(irq_WR_OVF_set, m_set[6])
  `FC(irq_WR_OVF_cleared, m_w[1][6] && m_wr && m_map && m_idx == 1 && PWDATA[6] && PSTRB[0])
  `FC(irq_WR_OVF_masked, m_w[1][6] && !m_w[2][6])
  `FC(irq_WR_OVF_drives_pin, m_w[1][6] && m_w[2][6] && irq)
  `FC(irq_RD_AVAIL_set, m_set[7])
  `FC(irq_RD_AVAIL_cleared, m_w[1][7] && m_wr && m_map && m_idx == 1 && PWDATA[7] && PSTRB[0])
  `FC(irq_RD_AVAIL_masked, m_w[1][7] && !m_w[2][7])
  `FC(irq_RD_AVAIL_drives_pin, m_w[1][7] && m_w[2][7] && irq)
  `FC(CMD_handshake, m_state_CMD && c_cmd_ready)
  `FC(CMD_backpressure, m_state_CMD && !c_cmd_ready)
  `FC(CMD_write_while_full, m_wr && m_map && m_idx == 6 && m_state_CMD)
  `FC(WR_handshake, m_state_WR && c_wr_ready)
  `FC(WR_backpressure, m_state_WR && !c_wr_ready)
  `FC(WR_write_while_full, m_wr && m_map && m_idx == 7 && m_state_WR)
  `FC(RD_capture, c_rd_valid && !m_state_RD)
  `FC(RD_backpressure, c_rd_valid && m_state_RD && !(m_rd && m_map && m_idx == 8))
  `FC(RD_pop, m_rd && m_map && m_idx == 8 && m_state_RD)
  `FC(RD_read_empty, m_rd && m_map && m_idx == 8 && !m_state_RD)
  `FC(RD_pop_and_capture, c_rd_valid && m_state_RD && m_rd && m_map && m_idx == 8)
  `FC_RST(reset_with_pending_irq, PRESETN && m_w[1] != 0 ##1 !PRESETN)
endmodule

bind ONFI_apb ONFI_apb_sva u_apb_sva (.*);
